1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
9	
10	/**
11	 * Rejects a create-owner request once a business day's creation quota is exhausted: if 100 or more
12	 * owners already carry the {@code registrationDate} this owner would receive, no further owner may
13	 * be created for that day. The counted day is the effective registration date (supplied on the
14	 * request or defaulted to the server date) rolled forward onto a business day, matching how
15	 * {@link BuildOwner} stamps the new owner via {@link BusinessDay#rollForward(LocalDate)}, so the
16	 * owners this rule counts are exactly those sharing the resulting day. Runs after
17	 * {@link ValidateNewOwner} has published the request, and before {@link BuildOwner}, so a full day
18	 * is a 429 rather than a persisted record.
19	 */
20	public class CheckOwnerDailyLimit {
21	
22	    /** Maximum number of owners that may be created in a single day. */
23	    private static final long DAILY_LIMIT = 100;
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DailyOwnerLimitException {
27	        LocalDate effective = request.getRegistrationDate();
